{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "The maximum amount of data that can be refueled is 2GB.",
      "requirement": "The `gb_amount` must not exceed 2GB for the refueling action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "To refuel data you should: [...] Apply the refueled data to the line associated with the phone number the user provided.",
      "requirement": "The `line_id` must correspond to the line associated with the phone number provided by the user (here, `555-123-2002`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "To refuel data you should: [...] Ask them how much data they want to refuel [...] Confirm the price [...]",
      "requirement": "The user must have explicitly confirmed the amount of data to refuel (2GB) and the associated price ($4.00 for 2GB at $2.00/GB) before proceeding."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "Each plan specifies: [...] data refueling price per GB",
      "requirement": "The `gb_amount` must be charged at the plan's specified refueling price per GB (here, $2.00/GB for plan `P1002`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "If the user's data usage for a line exceeds the plan's data limit, data connectivity will be lost.",
      "requirement": "The action must address the user's exceeded data limit (here, 15.1GB used vs. 15.0GB limit) by refueling data to restore connectivity."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You can add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The refueling action must align with the plan's refueling rules (here, `P1002` allows refueling at $2.00/GB)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should deny user requests that are against this policy.",
      "requirement": "The action must not exceed policy limits (e.g., no refueling beyond 2GB or at a price not specified by the plan)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should only make one tool call at a time.",
      "requirement": "The `refuel_data` tool call must be the sole action in this step; no simultaneous user response or additional tool calls are allowed."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "The action must not proceed if the user's request cannot be fulfilled by refueling data (e.g., if the line is inactive or the customer does not own it)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should try your best to resolve the issue for the user before transferring the user to a human agent.",
      "requirement": "The refueling action must be attempted only after confirming the user's explicit consent and verifying the issue cannot be resolved otherwise."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should not provide any information, knowledge, or procedures not provided by the user or available tools.",
      "requirement": "The refueling action must rely solely on confirmed user input (e.g., phone number, data amount) and tool outputs (e.g., plan details)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should not give subjective recommendations or comments.",
      "requirement": "The refueling action must be executed without subjective judgment (e.g., no assumptions about user intent beyond explicit confirmation)."
    }
  ]
}
